    /// C#: `internal void PerformMoveFromLocations(Player initiator, Dictionary<Location, Battalion> forceLocations, ILocationEvent evt, bool asAdvisors, bool byCaravan)` (Game_Move.cs:72)
    pub fn perform_move_from_locations(&mut self, initiator: PlayerIndex, force_locations: &NetDictionary<Location, Battalion>, evt: &GameEvent, as_advisors: bool, by_caravan: bool) {
        let Some(to) = evt.to_location(self) else { return };

        self.last_shipment_or_movement = Some(evt.clone());
        let was_occupied_before_move = self.is_occupied_territory(to.territory());
        let values: Vec<Battalion> = force_locations.values().cloned().collect();
        let dist = self.determine_maximum_move_distance(initiator, &values);
        let move_number = if matches!(evt, GameEvent::Move(_) | GameEvent::Caravan(_)) {
            self.moves_logged = self.moves_logged.wrapping_add(1);
            Some(self.moves_logged)
        } else {
            None
        };

        let from_territories = force_locations.keys().map(|l| l.territory()).cs_distinct();
        for from_territory in from_territories {
            let mut total_number_of_forces = 0;
            let mut total_number_of_special_forces = 0;

            // forceLocations is a local dictionary that nothing modifies, so the lazy Where can be collected.
            let in_territory: Vec<(Location, Battalion)> = force_locations
                .iter()
                .filter(|(k, _)| k.territory() == from_territory)
                .map(|(k, v)| (*k, v.clone()))
                .collect();
            for fl in in_territory {
                if fl.1.total_amount_of_forces() > 0 {
                    self.perform_move_from_location(initiator, fl.0, &fl.1, to, &mut total_number_of_forces, &mut total_number_of_special_forces, false);
                    // C# parity: Sandmaster is applied per source location (hazards 18).
                    self.check_sandmaster(initiator, to, dist, fl);
                }
            }

            if self.player(initiator).is(Faction::BeneGesserit) {
                Player::flip_forces(self, initiator, to, was_occupied_before_move && as_advisors);
            }

            if total_number_of_forces > 0 || total_number_of_special_forces > 0 {
                let from_locations: Vec<Location> = force_locations
                    .iter()
                    .filter(|(k, v)| k.territory() == from_territory && v.total_amount_of_forces() > 0)
                    .map(|(k, _)| *k)
                    .collect();
                self.log_move(initiator, from_territory, &from_locations, to, total_number_of_forces, total_number_of_special_forces, was_occupied_before_move && as_advisors, by_caravan, move_number);
            }
        }

        self.stone(Milestone::Move);
        self.flip_bene_gesserit_advisors_when_alone();
    }

    /// C#: `private void CheckSandmaster(Player initiator, Location to, int dist, KeyValuePair<Location, Battalion> fl)` (Game_Move.cs:106)
    pub fn check_sandmaster(&mut self, initiator: PlayerIndex, to: Location, dist: i32, fl: (Location, Battalion)) {
        if self.skilled_as_player_leader_skill(initiator, LeaderSkill::Sandmaster) {
            let faction = self.player(initiator).faction;
            let ignore_storm = faction == Faction::Fremen && self.applicable(Rule::FremenMayMoveIntoStorm);
            let paths = self.map.find_paths(fl.0, to, dist, ignore_storm, faction, &*self);
            let mut most_spice = 0;
            let mut path_with_most_spice: Option<Vec<Location>> = None;
            for p in paths {
                let amount_of_spice_locations = p.iter().filter(|l| self.resources_on_planet.contains_key(*l)).cs_distinct().len() as i32;
                if amount_of_spice_locations > most_spice {
                    most_spice = amount_of_spice_locations;
                    path_with_most_spice = Some(p);
                }
            }

            if let Some(path) = path_with_most_spice {
                if most_spice > 0 {
                    for loc in path {
                        if self.resources_on_planet.contains_key(&loc) {
                            self.change_resources_on_planet(loc, -1);
                        }
                    }

                    let pl = self.player_mut(initiator);
                    pl.resources = pl.resources.wrapping_add(most_spice);
                    let f = self.player(initiator).faction;
                    self.log(elems![f, " ", LeaderSkill::Sandmaster, " collects ", Payment::of(most_spice), " along the way"]);
                }
            }
        }
    }

    /// C#: `internal void PerformMoveFromLocation(Player initiator, Location from, Battalion battalion, Location to, ref int totalNumberOfForces, ref int totalNumberOfSp...` (Game_Move.cs:134)
    pub fn perform_move_from_location(&mut self, initiator: PlayerIndex, from: Location, battalion: &Battalion, to: Location, total_number_of_forces: &mut i32, total_number_of_special_forces: &mut i32, ignore_storm: bool) {
        let must_move_through_storm = self.must_move_through_storm(initiator, from, to, battalion);
        if !ignore_storm && (self.is_in_storm(to) || must_move_through_storm) {
            let kill_count;
            if self.player(initiator).is(Faction::Fremen) && !self.prevented(FactionAdvantage::FremenProtectedFromStorm) && self.applicable(Rule::FremenStormLosses) {
                kill_count = 0;
                Player::move_forces(self, initiator, from, to, battalion.amount_of_forces);
                Player::move_special_forces(self, initiator, from, to, battalion.amount_of_special_forces);
                let amount = TakeLosses::half_of(battalion.amount_of_forces, battalion.amount_of_special_forces);
                self.storm_losses_to_take.push(LossToTake { location: Some(to), amount, faction: battalion.faction });
            } else {
                kill_count = battalion.amount_of_forces.wrapping_add(battalion.amount_of_special_forces);
                Player::kill_forces(self, initiator, from, battalion.amount_of_forces, battalion.amount_of_special_forces, false);
            }

            if kill_count > 0 {
                let f = self.player(initiator).faction;
                let m = express!(kill_count, f, " forces are killed by the storm while travelling")
                    .with_log(ShipMoveLoss::new(f, true, true, kill_count, None));
                self.log(elems![m]);
            }
        } else {
            Player::move_forces(self, initiator, from, to, battalion.amount_of_forces);
            Player::move_special_forces(self, initiator, from, to, battalion.amount_of_special_forces);
        }

        *total_number_of_forces = total_number_of_forces.wrapping_add(battalion.amount_of_forces);
        *total_number_of_special_forces = total_number_of_special_forces.wrapping_add(battalion.amount_of_special_forces);
    }

    /// C#: `private bool MustMoveThroughStorm(Player initiator, Location from, Location to, Battalion moved)` (Game_Move.cs:167)
    pub fn must_move_through_storm(&self, initiator: PlayerIndex, from: Location, to: Location, moved: &Battalion) -> bool {
        let max = self.determine_maximum_move_distance(initiator, std::slice::from_ref(moved));
        let faction = self.player(initiator).faction;
        let targets_avoiding_storm = self.map.find_neighbours(from, max, false, faction, self, true);
        let targets_ignoring_storm = self.map.find_neighbours(from, max, true, faction, self, true);
        !targets_avoiding_storm.contains(&to) && targets_ignoring_storm.contains(&to)
    }

    /// C#: `internal void LogMove(Player initiator, Territory from, IEnumerable<Location> fromLocations, Location to, int forceAmount, int specialForceAmount, bool asAdv...` (Game_Move.cs:181)
    pub fn log_move(&mut self, initiator: PlayerIndex, from: Territory, from_locations: &[Location], to: Location, force_amount: i32, special_force_amount: i32, as_advisors: bool, by_caravan: bool, move_number: Option<i32>) {
        let bene_gesserit_as = self.player(initiator).is(Faction::BeneGesserit) && self.applicable(Rule::BeneGesseritAdvisors);
        let pl = self.player(initiator);
        let faction = pl.faction;
        let force = pl.force();
        let special_force = pl.special_force();
        let as_what: ExpressionElement = if as_advisors { special_force.into() } else { force.into() };
        let mut message = express!(
            Game::caravan_message(by_caravan),
            faction,
            " move ",
            express_part_if!(force_amount > 0; force_amount, force),
            express_part_if!(special_force_amount > 0; special_force_amount, special_force),
            " from ",
            from,
            " to ",
            to,
            express_part_if!(bene_gesserit_as; " as ", as_what)
        )
        .with_route(faction, from_locations.iter().copied(), Some(to));

        if let Some(nr) = move_number {
            message = message.with_log(MoveLogged::new(faction, nr, from, force_amount, special_force_amount, to, by_caravan, if bene_gesserit_as { Some(as_advisors) } else { None }));
        }

        self.log(elems![message]);
    }

